package com.kingoffjoss.pingo;
import android.app.*;import android.content.*;import android.content.pm.ServiceInfo;import android.content.res.Configuration;import android.graphics.Color;import android.graphics.PixelFormat;import android.os.*;import android.provider.Settings;import android.view.*;import android.webkit.*;import android.widget.*;import java.util.Random;
public class PingoService extends Service {
 private WindowManager wm;private WindowManager.LayoutParams params;private LinearLayout root,menu;private WebView web;private TextView speech;private final Handler handler=new Handler(Looper.getMainLooper());private final Random random=new Random();private boolean walking=false,dragging=false,ready=false,stopped=false;private int direction=1;private long lastWater;private BroadcastReceiver screen;
 private final Runnable tick=new Runnable(){public void run(){if(stopped||root==null)return;if(!Settings.canDrawOverlays(PingoService.this)){stopSelf();return;}if(root.getVisibility()==View.VISIBLE){if(walking&&!dragging&&menu.getVisibility()==View.GONE){int max=Math.max(0,screenWidth()-params.width),next=OverlayGeometry.nextX(params.x,direction*dp(2),screenWidth(),params.width);if(next==0||next==max)direction=-direction;params.x=next;updatePosition();}if(SystemClock.elapsedRealtime()-lastWater>30*60*1000L){say("Ei, vamos beber água? 💧");command("wave");lastWater=SystemClock.elapsedRealtime();}}handler.postDelayed(this,50);}};
 private final Runnable emotion=new Runnable(){public void run(){if(stopped)return;if(!walking&&!dragging&&root!=null&&root.getVisibility()==View.VISIBLE&&menu.getVisibility()==View.GONE){String[] actions={"idle","curious","wave","proud","stretch","proud","think"};command(actions[random.nextInt(actions.length)]);}handler.postDelayed(this,12000+random.nextInt(10000));}};
 @Override public IBinder onBind(Intent intent){return null;}
 @Override public int onStartCommand(Intent intent,int flags,int startId){if(intent!=null&&"STOP".equals(intent.getAction())){stopSelf();return START_NOT_STICKY;}if(root!=null)return START_NOT_STICKY;if(!Settings.canDrawOverlays(this)){stopSelf();return START_NOT_STICKY;}try{foreground();createOverlay();}catch(RuntimeException e){stopSelf();}return START_NOT_STICKY;}
 private void foreground(){NotificationManager manager=getSystemService(NotificationManager.class);manager.createNotificationChannel(new NotificationChannel("pingo-overlay","Pingo flutuante",NotificationManager.IMPORTANCE_LOW));PendingIntent open=PendingIntent.getActivity(this,0,new Intent(this,MainActivity.class),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);PendingIntent stop=PendingIntent.getService(this,1,new Intent(this,PingoService.class).setAction("STOP"),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);Notification notification=new Notification.Builder(this,"pingo-overlay").setSmallIcon(com.kingoffjoss.pingo.R.drawable.ic_pingo).setContentTitle("Pingo está por aqui 💚").setContentText("Toque no mascote para cuidar. Use Parar para fechar.").setContentIntent(open).setOngoing(true).addAction(new Notification.Action.Builder(null,"Parar",stop).build()).build();if(Build.VERSION.SDK_INT>=34)startForeground(7,notification,ServiceInfo.FOREGROUND_SERVICE_TYPE_SPECIAL_USE);else startForeground(7,notification);}
 private void createOverlay(){wm=(WindowManager)getSystemService(WINDOW_SERVICE);root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setGravity(Gravity.CENTER);root.setBackgroundColor(Color.TRANSPARENT);params=new WindowManager.LayoutParams(dp(230),WindowManager.LayoutParams.WRAP_CONTENT,WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE|WindowManager.LayoutParams.FLAG_NOT_TOUCH_MODAL,PixelFormat.TRANSLUCENT);params.gravity=Gravity.TOP|Gravity.LEFT;params.x=Math.max(0,screenWidth()-dp(245));params.y=dp(220);
  speech=new TextView(this);speech.setTextColor(Color.rgb(38,85,66));speech.setTextSize(13);speech.setGravity(Gravity.CENTER);speech.setBackgroundColor(Color.rgb(244,253,247));speech.setPadding(dp(8),dp(8),dp(8),dp(8));speech.setText("Oi! Arraste ou toque em mim. 💚");root.addView(speech,new LinearLayout.LayoutParams(-1,dp(48)));
  web=new WebView(this);web.setBackgroundColor(Color.TRANSPARENT);web.getSettings().setJavaScriptEnabled(true);web.getSettings().setDomStorageEnabled(false);web.getSettings().setAllowFileAccess(false);web.getSettings().setAllowContentAccess(false);web.getSettings().setBlockNetworkLoads(true);web.getSettings().setMediaPlaybackRequiresUserGesture(true);web.setWebViewClient(new WebViewClient(){@Override public void onPageFinished(WebView v,String url){ready=true;command("idle");}@Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){return true;}@Override public WebResourceResponse shouldInterceptRequest(WebView v,WebResourceRequest request){return request.getUrl().toString().startsWith("file:///android_asset/")?null:new WebResourceResponse("text/plain","UTF-8",new java.io.ByteArrayInputStream(new byte[0]));}});root.addView(web,new LinearLayout.LayoutParams(-1,dp(180)));web.loadUrl("file:///android_asset/overlay.html");
  menu=new LinearLayout(this);menu.setOrientation(LinearLayout.VERTICAL);menu.setPadding(dp(4),0,dp(4),dp(6));menu.setBackgroundColor(Color.rgb(244,253,247));row("Carinho",()->{walking=false;command("proud");say("Adorei o carinho! 💚");},"Comer",()->{walking=false;command("eat");say("Nhac! Obrigado pelo lanche.");});row("Dormir",()->{walking=false;command("sleep");say("Vou descansar um pouquinho… zzz");},"Passear",()->{walking=!walking;command(walking?"walk":"idle");say(walking?"Vamos dar uma volta?":"Vou ficar aqui com você.");});row("Mudar cor",()->web.evaluateJavascript("window.pingoColor&&window.pingoColor()",null),"Fechar Pingo",this::stopSelf);menu.setVisibility(View.GONE);root.addView(menu);View.OnClickListener toggle=v->{menu.setVisibility(menu.getVisibility()==View.GONE?View.VISIBLE:View.GONE);menu.post(()->{clampPosition();updatePosition();});};web.setOnClickListener(toggle);speech.setOnClickListener(toggle);View.OnTouchListener drag=dragListener();web.setOnTouchListener(drag);speech.setOnTouchListener(drag);wm.addView(root,params);lastWater=SystemClock.elapsedRealtime();handler.postDelayed(tick,50);handler.postDelayed(emotion,12000);
  screen=new BroadcastReceiver(){@Override public void onReceive(Context c,Intent i){if(Intent.ACTION_SCREEN_OFF.equals(i.getAction())){root.setVisibility(View.GONE);web.onPause();}else if(Intent.ACTION_USER_PRESENT.equals(i.getAction())){root.setVisibility(View.VISIBLE);web.onResume();clampPosition();updatePosition();}}};IntentFilter filter=new IntentFilter();filter.addAction(Intent.ACTION_SCREEN_OFF);filter.addAction(Intent.ACTION_USER_PRESENT);if(Build.VERSION.SDK_INT>=33)registerReceiver(screen,filter,Context.RECEIVER_NOT_EXPORTED);else registerReceiver(screen,filter);
 }
 private View.OnTouchListener dragListener(){return new View.OnTouchListener(){float downX,downY;int startX,startY;boolean moved;@Override public boolean onTouch(View v,android.view.MotionEvent e){switch(e.getActionMasked()){case android.view.MotionEvent.ACTION_DOWN:downX=e.getRawX();downY=e.getRawY();startX=params.x;startY=params.y;dragging=true;moved=false;return true;case android.view.MotionEvent.ACTION_MOVE:float dx=e.getRawX()-downX,dy=e.getRawY()-downY;if(Math.hypot(dx,dy)>dp(6))moved=true;if(moved){params.x=startX+Math.round(dx);params.y=startY+Math.round(dy);clampPosition();updatePosition();}return true;case android.view.MotionEvent.ACTION_UP:dragging=false;if(!moved)v.performClick();else say("Gostei deste cantinho! 💚");return true;case android.view.MotionEvent.ACTION_CANCEL:dragging=false;return true;default:return false;}}};}
 private void row(String a,Runnable aa,String b,Runnable bb){LinearLayout row=new LinearLayout(this);for(int i=0;i<2;i++){Button button=new Button(this);button.setText(i==0?a:b);button.setTextSize(11);button.setAllCaps(false);button.setMinHeight(dp(44));Runnable action=i==0?aa:bb;button.setOnClickListener(v->action.run());row.addView(button,new LinearLayout.LayoutParams(0,dp(48),1));}menu.addView(row);}
 private void command(String action){if(ready&&web!=null)web.evaluateJavascript("window.pingoAction&&window.pingoAction("+org.json.JSONObject.quote(action)+")",null);}
 private void say(String text){if(speech!=null)speech.setText(text);}
 private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
 private int screenWidth(){return getResources().getDisplayMetrics().widthPixels;}
 private void clampPosition(){if(params==null||root==null)return;params.x=OverlayGeometry.clamp(params.x,0,screenWidth()-params.width);params.y=OverlayGeometry.clamp(params.y,0,getResources().getDisplayMetrics().heightPixels-Math.max(root.getHeight(),dp(240))-dp(48));}
 private void updatePosition(){if(wm!=null&&root!=null&&root.isAttachedToWindow())try{wm.updateViewLayout(root,params);}catch(IllegalArgumentException|SecurityException e){stopSelf();}}
 @Override public void onConfigurationChanged(Configuration config){super.onConfigurationChanged(config);handler.post(()->{clampPosition();updatePosition();});}
 @Override public void onDestroy(){stopped=true;handler.removeCallbacksAndMessages(null);if(screen!=null)try{unregisterReceiver(screen);}catch(IllegalArgumentException ignored){}if(root!=null&&root.isAttachedToWindow())wm.removeView(root);if(web!=null){web.stopLoading();web.destroy();web=null;}stopForeground(STOP_FOREGROUND_REMOVE);super.onDestroy();}
}
